from lib import *
S = SS('w99')
steps = [
    step("FTP 的控制连接是纯文本的命令加三位数字的答复,和 SMTP 很像。本机 pyftpdlib 服务器:220 问候 → USER alice(331 Username ok, send password.)→ PASS(230 Login successful.)→ SYST(215 UNIX Type: L8)→ FEAT(多行答复,“211-Features supported:” 开头,每行一个特性:EPRT、EPSV、MDTM、MFMT、MLST、REST STREAM、SIZE、TVFS、UTF8,“211 End FEAT.” 结尾,和 SMTP 的 250- 一样)→ PWD(257 \"/\" is the current directory.)→ CWD pub(250)→ TYPE I(200 Type set to: Binary.)→ SIZE f0.txt(213 700)→ QUIT(221 Goodbye.)。PASS 把密码明文写在控制连接上,第四节抓包验证。", t=tl(S(1)), mark=lidx(S(1), 'C: USER alice', 'C: PASS', 'C: FEAT'), done=lidx(S(1), 'S: 220', 'S: 230', 'S: 215', 'S: 211 End FEAT', 'S: 213 700'), kv=KV([['登录', '331 → 230'], ['FEAT', '211- 开头多行,211 结尾'], ['SIZE f0.txt', '213 700'], ['TYPE I', '200 Binary']], ['FEAT'])),
    step("被动模式(PASV):文件内容和目录列表不走控制连接,要另开一条数据连接。客户端发 PASV,服务器答 “227 Entering passive mode (127,0,0,1,37,8)”——前四个数字是 IP 地址,后两个是端口的高低字节:端口 = 37 × 256 + 8 = 9480。客户端于是另开一条 TCP 连接到 127.0.0.1:9480(数据连接)。然后在控制连接上发 LIST,服务器答 125 Data connection already open. Transfer starting.,目录列表(694 字节,第一行是 big.bin 的 -rw-r--r-- 200000 字节)走数据连接传来;传完服务器关闭数据连接,控制连接上再收到 226 Transfer complete.。每个传输一条新的数据连接,数据连接用完即关。", t=tl(S(2)), mark=lidx(S(2), 'C: PASV', '227 里的', '客户端另开一条', 'C: LIST'), done=lidx(S(2), '数据连接上收到', 'S: 226', 'S: 125'), kv=KV([['227 (…,37,8)', '端口 37×256+8 = 9480'], ['数据连接', '客户端另开,传 694 字节目录'], ['控制连接', '125 Transfer starting → 226 Transfer complete']], ['227 (…,37,8)'])),
    step("EPSV(扩展被动模式,同时支持 IPv6):答复 “229 Entering extended passive mode (|||9466|)”,只给端口号,地址沿用控制连接的。主动模式(PORT):客户端自己监听一个端口(58494),发 PORT 127,0,0,1,228,126(228 × 256 + 126 = 58494),服务器答 200 Active data connection established.;随后 LIST 时,**服务器主动连接客户端的 58494 端口**(数据连接服务器一侧的端口是 58496),收到 694 字节的目录列表,控制连接上答复 125。方向与被动模式相反。被动模式里数据连接由客户端发起,穿 NAT 友好;主动模式由服务器发起,客户端在 NAT 或防火墙后面就收不到——这就是 FTP 在现代网络里首选被动模式的原因。", t=tl(S(3)), mark=lidx(S(3), 'C: EPSV', 'PORT 127,0,0,1'), done=lidx(S(3), 'S: 229', '被动模式里数据连接'), kv=KV([['EPSV', '229 (|||9466|)'], ['PORT 127,0,0,1,228,126', '客户端监听 58494'], ['主动模式', '服务器连客户端'], ['被动模式', '客户端连服务器']], ['主动模式'])),
    step("抓包看安全性:控制连接的全部字节(241 字节)里,可以直接读到 “USER alice”“PASS pa55w0rd”“CWD pub”“RETR f0.txt”——用户名、密码、目录、文件名都是明文。路径上任何一个能抓包的地方都能读走密码。FTPS(FTP over TLS)和 SFTP(基于 SSH,与 FTP 无关)是后来补的。", t=tl(S(4)), mark=lidx(S(4), '控制连接的全部字节'), done=lidx(S(4), '所以 FTP 的密码'), b=bars([['控制连接总字节', 241, '241 字节'], ['明文密码', 8, 'pa55w0rd']], 241, mark=[1], done=[0]), kv=KV([['可读到', 'USER alice、PASS pa55w0rd、CWD、RETR'], ['补救', 'FTPS(TLS)、SFTP(SSH)']], ['可读到'])),
    step("代价:每个文件都要一条新的数据连接。lo0 上 netlab 每方向 50 ms(往返 100 ms),被动模式。登录(TCP 握手 + 220 + USER + PASS + CWD + TYPE)中位 608 ms ≈ 6.1 个往返。取 10 个小文件(每个约 700 字节)中位 4051 ms,平均每个 405 ms ≈ 4.1 个往返:PASV 1 个、连数据端口 1 个、RETR 1 个,外加传输结束的确认。取一个 200000 字节的大文件 505 ms。对比 HTTP/1.1 keep-alive:取一个小文件只要 1 个往返。所以 FTP 不适合大量小文件,适合少量大文件。", t=tl(S(5)), mark=lidx(S(5), '登录(TCP', '取一个 200000'), done=lidx(S(5), '对比 HTTP/1.1'), b=bars([['登录', 608, '608 ms ≈ 6.1 RTT'], ['10 个小文件 合计', 4051, '4051 ms'], ['每个小文件', 405, '405 ms ≈ 4.1 RTT'], ['200000 字节大文件', 505, '505 ms']], 4051, mark=[1], done=[0, 2, 3]), kv=KV([['登录', '约 6.1 个往返'], ['每个小文件', '约 4.1 个往返(PASV + 数据连接 + RETR + 收尾)'], ['HTTP/1.1 keep-alive', '1 个往返']], ['每个小文件'])),
]
A = mkartw('w99', 99, '网络协议,FTP,控制连接,数据连接,被动模式,主动模式,PASV,真实验证,动画演示',
    '实测 FTP:控制连接是明文命令 + 三位数字答复;PASV 的 (127,0,0,1,37,8) 就是端口 9480;主动模式由服务器反向连客户端;抓包能读到 USER / PASS 明文;100 ms 往返下登录约 6.1 个往返,每个小文件约 4.1 个往返。',
    'FTP 是最古老的文件传输协议之一,也是最“怪”的:一条控制连接发命令,每次传输再另开一条数据连接,还分主动和被动两种方向。这篇在本机起一个 FTP 服务器,逐个把这些怪处看清楚,并量出它为什么不适合传一大堆小文件。',
    [('37 × 256 + 8 = 9480', 'PASV 答复 (127,0,0,1,37,8) 里端口的计算'), ('241 字节', '控制连接上能直接读到密码 pa55w0rd 的明文流量'), ('4.1 个往返', '100 ms 往返下被动模式取一个小文件的平均代价')],
    [('控制连接', '<p>文本命令与三位数字答复,多行答复用 “211-” 到 “211 ”,和 SMTP 同一种风格。</p>'),
     ('被动模式', '<p>PASV 报告端口,客户端再连;数据连接用完即关。</p>'),
     ('主动与 EPSV', '<p>主动模式 PORT 让服务器反过来连客户端;EPSV 只给端口,支持 IPv6。</p>'),
     ('明文', '<p>用户名、密码、文件名全是明文。</p>'),
     ('代价', '<p>每个文件一条新数据连接,小文件约 4.1 个往返;登录约 6.1 个往返。</p>')],
    steps,
    [ENV_W + '。全部在本机,服务器是 pyftpdlib(临时目录,临时用户,用后删除);被动端口范围我限定在 9460~9489 以便 netlab 作用;第五节每组 2 次取中位,只取了 10 个 700 字节的小文件与一个 200000 字节的大文件;主动模式的数据连接服务器端口(58496)是 pyftpdlib 的行为',
     '没有验证:FTPS(显式 AUTH TLS / 隐式 990);真实公共 FTP 服务器的行为;ASCII 模式的换行转换;REST 断点续传;MLSD / MLST 的机器可读列表;NAT 设备的 FTP ALG(应用层网关)改写 PORT / PASV 地址;防火墙对随机被动端口的处理'],
    'FTP')
